cat >> src/pickList.test.ts <<'EOF'

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({
  bin,
  sku,
  qty,
  expires,
});

test("an item covered by one lot yields one pick", () => {
  const text = "ORDER 1001\n  OLIVE-500 x3";
  expect(buildPickList(text, [lot("A-01-1", "OLIVE-500", 10)])).toEqual({
    picks: [{ bin: "A-01-1", sku: "OLIVE-500", qty: 3, orderId: "1001" }],
    shortages: [],
  });
});
EOF
bun test 2>&1 | grep -E "pass|fail"
